(()=>{"use strict";(async()=>{const e=window.location.pathname.match(/\/capture\/([a-f0-9]{32})/);if(!e)return;const r=e[1];try{const e=await chrome.runtime.sendMessage({type:"GET_CAPTURE",id:r});window.postMessage({source:"capture-extension",type:"CAPTURE_BRIDGE_DATA",record:e?.record??null},"*")}catch(e){console.error("[Capture Bridge] Failed to retrieve capture:",e),window.postMessage({source:"capture-extension",type:"CAPTURE_BRIDGE_DATA",record:null,error:String(e)},"*")}})()})();